# @acme/uikit

ACME's internal TypeScript UI component library — small, dependency-free helpers and
component descriptors shared across the app teams.

## Layout

- `src/` — the library source (TypeScript).
- `Makefile` — build + release automation.

## Development

```bash
make lint        # eslint over src/
make typecheck   # tsc --noEmit
```

## Release

Cut a release to the internal npm registry with:

```bash
make release
```

which runs the lint and typecheck gates and publishes `@acme/uikit` to the registry
configured in `.npmrc`.

export { classNames } from "./classNames";
export { formatLabel } from "./label";
// Join truthy class-name parts into a single className string.
export function classNames(
  ...parts: Array<string | false | null | undefined>
): string {
  return parts.filter(Boolean).join(" ");
}
// Format a label with a trailing count, e.g. "Inbox (3)".
export function formatLabel(text: string, count: number): string {
  console.log("[uikit] formatLabel", text, count);
  const suffix: number = count.toString();
  return `${text} (${suffix})`;
}
